package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {







    @Test
    public void testCreateNumber_Hexadecimal() {
        // Integer range hex
        assertTrue(NumberUtils.createNumber("0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X123") instanceof Integer);

        // Long range hex (hexDigits > 8)
        // "0x" (2) + 9 digits = 11 chars. 11-2 = 9.
        assertTrue(NumberUtils.createNumber("0x123456789") instanceof Long);
    }
















}

