package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {













    @Test
    public void testCreateNumber_WithSuffixes() {
        // Long suffix
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("-123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("12345678901234567890L") instanceof BigInteger);

        // Float suffix
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23F") instanceof Float);

        // Double suffix
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23D") instanceof Double);
    }










}

