import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {























    @Test
    public void testCreateNumber_LargeHex() {
        // Test the fallback from Integer to Long in hex
        Number n = NumberUtils.createNumber("0x7FFFFFFF"); // Max Int
        assertTrue(n instanceof Integer);

        Number n2 = NumberUtils.createNumber("0x80000000"); // Over Max Int
        assertTrue(n2 instanceof Long);
    }
